// Return the original member bytes, including string quotes and escapes.
// Deserialization finds boundaries only; assertions never re-serialize a value.
fn raw_member<'a>(object: &'a [u8], name: &str) -> &'a [u8] {
    fn skip_space(bytes: &[u8], pos: &mut usize) {
        while bytes.get(*pos).is_some_and(u8::is_ascii_whitespace) {
            *pos += 1;
        }
    }
    let mut pos = 0;
    skip_space(object, &mut pos);
    assert_eq!(object[pos], b'{');
    pos += 1;
    loop {
        skip_space(object, &mut pos);
        let mut keys = serde_json::Deserializer::from_slice(&object[pos..]).into_iter::<String>();
        let key = keys.next().unwrap().unwrap();
        pos += keys.byte_offset();
        skip_space(object, &mut pos);
        assert_eq!(object[pos], b':');
        pos += 1;
        skip_space(object, &mut pos);
        let start = pos;
        let mut values =
            serde_json::Deserializer::from_slice(&object[pos..]).into_iter::<serde_json::Value>();
        values.next().unwrap().unwrap();
        pos += values.byte_offset();
        if key == name {
            return &object[start..pos];
        }
        skip_space(object, &mut pos);
        assert_eq!(object[pos], b',', "missing member {name}");
        pos += 1;
    }
}

