/// The library writes no startup diagnostic; the CLI owns the
/// `mutations_enabled` warning line.
#[test]
fn serve_io_writes_no_startup_diagnostic() {
    for mode in ["enabled", "disabled"] {
        let child = std::process::Command::new(std::env::current_exe().unwrap())
            .args(["--exact", "startup_warning_child", "--nocapture"])
            .env("ELASTICCTL_TEST_MUTATION_WARNING", mode)
            .output()
            .unwrap();
        assert!(child.status.success(), "{:?}", child);
        assert_eq!(String::from_utf8(child.stderr).unwrap(), "", "mode {mode}");
    }
}

